package users

import "time"

const activeWindow = 30 * 24 * time.Hour

// User is one account holder.
type User struct {
	id        string
	blocked   bool
	lastLogin time.Time
}

// New returns an unblocked user who last logged in at lastLogin.
func New(id string, lastLogin time.Time) User {
	return User{id: id, lastLogin: lastLogin}
}

// ID returns the user's identifier.
func (u User) ID() string {
	return u.id
}

// Block returns a copy of the user marked as blocked.
func (u User) Block() User {
	u.blocked = true
	return u
}

// IsBlocked reports whether the user has been blocked.
func (u User) IsBlocked() bool {
	return u.blocked
}

// IsActive reports whether the user logged in within the active window before now.
func (u User) IsActive(now time.Time) bool {
	return now.Sub(u.lastLogin) <= activeWindow
}
